#if os(iOS) || os(visionOS)
// P15: track only the exact token-completion suffix (including generated
// newline/comment delimiters), never equal authored text.
private var generatedClosingBrackets: [Int: unichar] = [:]

func forgetGeneratedClosingBrackets() {
  generatedClosingBrackets.removeAll()
}

func rememberGeneratedClosingBrackets(in range: NSRange) {
  guard range.location >= 0, range.length >= 0, NSMaxRange(range) <= length else { return }
  let source = string as NSString
  for index in range.location..<NSMaxRange(range) {
    let unit = source.character(at: index)
    generatedClosingBrackets[index] = unit
  }
}

func consumeGeneratedClosingBracket(_ replacement: String, at range: NSRange) -> Bool {
  guard range.length == 0, range.location >= 0, range.location < length,
        replacement.utf16.count == 1, let unit = replacement.utf16.first,
        generatedClosingBrackets[range.location] == unit,
        (string as NSString).character(at: range.location) == unit else { return false }
  generatedClosingBrackets.removeValue(forKey: range.location)
  return true
}

private func adjustGeneratedClosingBrackets(for range: NSRange, replacement: String) {
  // Deletion/replacement invalidates provenance. Ordinary typed insertion shifts it.
  guard range.length == 0, !replacement.isEmpty else {
    forgetGeneratedClosingBrackets()
    return
  }
  let delta = (replacement as NSString).length
  generatedClosingBrackets = Dictionary(uniqueKeysWithValues: generatedClosingBrackets.map {
    (index, unit) in (index >= range.location ? index + delta : index, unit)
  })
}
#endif

// MARK: Initialisers

// P15: only direct keyboard typing may consume a known generated closer.
fileprivate var processingDirectInsertion = false
fileprivate var directInsertionSelection: NSRange?
private var processingPaste = false

override func insertText(_ text: String) {
  let storage = optCodeStorage
  if directInsertionSelection != selectedRange || selectedRange.length != 0 ||
      markedTextRange != nil || text.count != 1 || processingPaste {
    storage?.forgetGeneratedClosingBrackets()
  }
  let wasProcessing = processingDirectInsertion
  processingDirectInsertion = true
  defer {
    directInsertionSelection = selectedRange
    processingDirectInsertion = wasProcessing
  }
  if !processingPaste, markedTextRange == nil,
     storage?.consumeGeneratedClosingBracket(text, at: selectedRange) == true {
    selectedRange = NSRange(location: selectedRange.location + 1, length: 0)
    return
  }
  super.insertText(text)
}

override func deleteBackward() {
  optCodeStorage?.forgetGeneratedClosingBrackets()
  directInsertionSelection = nil
  super.deleteBackward()
}

override func paste(_ sender: Any?) {
  optCodeStorage?.forgetGeneratedClosingBrackets()
  directInsertionSelection = nil
  processingPaste = true
  defer { processingPaste = false }
  super.paste(sender)
}

