func textViewDidChangeSelection(_ textView: UITextView) {
  guard let codeView = textView as? CodeView else { return }

  if !codeView.processingDirectInsertion, codeView.directInsertionSelection != codeView.selectedRange {
    codeView.optCodeStorage?.forgetGeneratedClosingBrackets()
    codeView.directInsertionSelection = nil
  }
  selectionDidChange?(textView)
